// ---- shared art-test plumbing ----------------------------------------------

// artJPEG encodes a small JPEG whose pixels carry seed — distinct seeds never
// share a content address (the api-side twin of the art package's own helper).
func artJPEG(t *testing.T, seed byte) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, 4, 6))
	for y := 0; y < 6; y++ {
		for x := 0; x < 4; x++ {
			img.Set(x, y, color.RGBA{R: seed, G: uint8(int(seed) + x), B: uint8(int(seed) + y), A: 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		t.Fatalf("encode jpeg: %v", err)
	}
	return buf.Bytes()
}

// sha256HexOf is the content address of b (the blob dir name).
func sha256HexOf(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// artUpstream is the local stand-in for the plugin upstream: fixed path →
// bytes, plus a per-path hit counter so tests can prove the negative —
// "no upstream contact" — where the contract demands it.
type artUpstream struct {
	server *httptest.Server
	mu     sync.Mutex
	counts map[string]int
}

// hits is one path's request count so far.
func (u *artUpstream) hits(path string) int {
	u.mu.Lock()
	defer u.mu.Unlock()
	return u.counts[path]
}

// total is the request count across all paths.
func (u *artUpstream) total() int {
	u.mu.Lock()
	defer u.mu.Unlock()
	n := 0
	for _, c := range u.counts {
		n += c
	}
	return n
}

// newArtUpstream serves the given files (missing paths 404) and counts every
// dial per path.
func newArtUpstream(t *testing.T, files map[string][]byte) *artUpstream {
	t.Helper()
	u := &artUpstream{counts: map[string]int{}}
	u.server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		u.mu.Lock()
		u.counts[r.URL.Path]++
		u.mu.Unlock()
		body, ok := files[r.URL.Path]
		if !ok {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		_, _ = w.Write(body)
	}))
	t.Cleanup(u.server.Close)
	return u
}

// artTestApp is the wired router under test: Deps.Art over st and a stub
// ModulePresentation closure serving sourceChain verbatim, plus the client
// token minted through the real pairing flow.
type artTestApp struct {
	handler http.Handler
	client  string // the minted device token (RoleClient)
}

// newArtTestApp builds the app and mints one paired device the slow way
// (create → approve → pick up), so browse-group assertions run a real
// RoleClient credential.
func newArtTestApp(t *testing.T, st *store.Store, artSvc *art.Service, chain []titleSourceBinding) artTestApp {
	t.Helper()
	devices := pairing.NewService(st, nil)
	h := New(Deps{
		AdminToken: adminToken,
		Store:      st,
		Pairing:    devices,
		Art:        artSvc,
		ModulePresentation: func(_ context.Context, _ string, _ int64) (ModulePresentation, error) {
			return ModulePresentation{SourceChain: chain}, nil
		},
	})
	create := doRequest(t, h, http.MethodPost, "/api/v1/pair", "", "")
	defer create.Body.Close()
	var pr pairCreateResponse
	if err := json.NewDecoder(create.Body).Decode(&pr); err != nil {
		t.Fatalf("decode pair create: %v", err)
	}
	approve := doRequest(t, h, http.MethodPost, "/api/v1/admin/pairings/"+pr.PairingID+"/approve", "", adminToken)
	defer approve.Body.Close()
	if approve.StatusCode != http.StatusOK {
		t.Fatalf("approve = %d, want 200", approve.StatusCode)
	}
	wait := doRequest(t, h, http.MethodGet, "/api/v1/pair/"+pr.PairingID+"/wait", "", "")
	defer wait.Body.Close()
	var wr pairWaitResponse
	if err := json.NewDecoder(wait.Body).Decode(&wr); err != nil {
		t.Fatalf("decode pair wait: %v", err)
	}
	if wr.DeviceToken == "" {
		t.Fatalf("approved pairing carried no device token: %+v", wr)
	}
	return artTestApp{handler: h, client: wr.DeviceToken}
}

// doUpload fires one multipart request at the handler — doRequest's multipart
// twin (the body reader plus its FormDataContentType).
func doUpload(t *testing.T, h http.Handler, method, path string, body io.Reader, contentType, token string) *http.Response {
	t.Helper()
	req := httptest.NewRequest(method, path, body)
	req.Header.Set("Content-Type", contentType)
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

// multipartFile builds a one-part multipart body named "file" — the upload
// field name the POST side of the poster route reads.
func multipartFile(t *testing.T, b []byte) (io.Reader, string) {
	t.Helper()
	var buf bytes.Buffer
	w := multipart.NewWriter(&buf)
	fw, err := w.CreateFormFile("file", "poster.jpg")
	if err != nil {
		t.Fatalf("create form file: %v", err)
	}
	if _, err := fw.Write(b); err != nil {
		t.Fatalf("write form file: %v", err)
	}
	if err := w.Close(); err != nil {
		t.Fatalf("close multipart writer: %v", err)
	}
	return &buf, w.FormDataContentType()
}

// putArtSeries upserts one series row carrying the given raw document.
func putArtSeries(t *testing.T, st *store.Store, lib int64, relPath string, doc json.RawMessage) {
	t.Helper()
	if err := st.PutSeries(context.Background(), store.Series{
		ModuleID: "serial", LibraryID: lib, RelativePath: relPath, Document: doc, SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
}

// artSeriesDoc builds the minimal document carrying one namespace poster.
func artSeriesDoc(ns, posterURL string) json.RawMessage {
	return json.RawMessage(`{"sources":{` + jsonQuote(ns) + `:{"poster":` + jsonQuote(posterURL) + `}}}`)
}

// jsonQuote is the JSON string form of s (document literals in tests).
func jsonQuote(s string) string {
	b, err := json.Marshal(s)
	if err != nil {
		panic(err) // a Go string always marshals
	}
	return string(b)
}

// decodeSeriesList pulls the served series list (the wire envelope the
// listings write).
func decodeSeriesList(t *testing.T, resp *http.Response) []seriesDTO {
	t.Helper()
	var out seriesListResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		t.Fatalf("decode series list: %v", err)
	}
	return out.Items
}

// artworkOf finds one relative path's served artwork ("" = field omitted).
func artworkOf(t *testing.T, items []seriesDTO, relPath string) string {
	t.Helper()
	for _, it := range items {
		if it.RelativePath == relPath {
			return it.Artwork
		}
	}
	t.Fatalf("series %q missing from the served list", relPath)
	return ""
}

// seriesIDOf loads the minted series id for (lib, relPath).
func seriesIDOf(t *testing.T, st *store.Store, lib int64, relPath string) string {
	t.Helper()
	sr, err := st.GetSeriesByPath(context.Background(), lib, relPath)
	if err != nil {
		t.Fatalf("GetSeriesByPath: %v", err)
	}
	return sr.ID
}

// TestArtComposition covers the composition precedence (artwork): the
// override tier (the pinned token rides the object route's proxy URL), the
// chain tier (a staged winner proxied, an unstaged winner raw — the read
// never blocks), honest absence, and the corrupt-document floor. One batched
// read composes the whole page; the only upstream dial allowed is the
// single background handoff for the unstaged winner (fetch-once economics).
func TestArtComposition(t *testing.T) {
	ctx := context.Background()
	st := openAPIStore(t)
	svc := art.NewService(st, t.TempDir())

	body := artJPEG(t, 0xC0)
	up := newArtUpstream(t, map[string][]byte{"/real.jpg": body})
	sha := sha256HexOf(body)
	if _, err := svc.Acquire(ctx, up.server.URL+"/real.jpg", art.KindPoster); err != nil {
		t.Fatalf("stage poster: %v", err)
	}
	// The override pins a token whose bytes were never stored: composition
	// stamps the proxy URL without stat-ing the blob — the object route
	// answers 404 canonically if the bytes are ever absent.
	pinnedSHA := sha256HexOf(artJPEG(t, 0x01))

	lib, err := st.CreateLibrary(ctx, "serial", "/media/art", "Art")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putArtSeries(t, st, lib, "Override", artSeriesDoc("shikimori", up.server.URL+"/real.jpg"))
	putArtSeries(t, st, lib, "Staged", artSeriesDoc("shikimori", up.server.URL+"/real.jpg"))
	putArtSeries(t, st, lib, "Unstaged", artSeriesDoc("shikimori", up.server.URL+"/never.jpg"))
	putArtSeries(t, st, lib, "Absent", artSeriesDoc("shikimori", ""))
	// A wrong-typed poster field: unparseable for the walk (floors to
	// absence), yet still a marshable wire document.
	putArtSeries(t, st, lib, "Corrupt", json.RawMessage(`{"sources":{"shikimori":{"poster":42}}}`))
	if _, err := st.UpsertArtOverride(ctx, seriesIDOf(t, st, lib, "Override"), "series", "art_"+pinnedSHA); err != nil {
		t.Fatalf("UpsertArtOverride: %v", err)
	}

	app := newArtTestApp(t, st, svc, []titleSourceBinding{{ID: "shikimori", Enabled: true}})
	resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/series?library="+strconv.FormatInt(lib, 10), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	items := decodeSeriesList(t, resp)

	if got := artworkOf(t, items, "Override"); got != artObjectPath+"art_"+pinnedSHA {
		t.Fatalf("override artwork = %q, want the proxy URL of the pinned token", got)
	}
	if got := artworkOf(t, items, "Staged"); got != artObjectPath+"art_"+sha {
		t.Fatalf("staged chain artwork = %q, want the proxy URL %q", got, artObjectPath+"art_"+sha)
	}
	if got := artworkOf(t, items, "Unstaged"); got != up.server.URL+"/never.jpg" {
		t.Fatalf("unstaged chain artwork = %q, want the raw remote URL", got)
	}
	if got := artworkOf(t, items, "Absent"); got != "" {
		t.Fatalf("absent artwork = %q, want the field omitted", got)
	}
	if got := artworkOf(t, items, "Corrupt"); got != "" {
		t.Fatalf("corrupt document artwork = %q, want the field omitted (floor, never an error)", got)
	}
	// The batched read never re-fetches a staged URL (one dial = the setup
	// Acquire) and the unstaged winner is handed off exactly once.
	if n := up.hits("/real.jpg"); n != 1 {
		t.Fatalf("staged URL dials = %d, want 1 (setup only; the read probes nothing)", n)
	}
	// The handoff is asynchronous (D4): give the background goroutine its
	// moment, then expect exactly one dial (the pending map dedups).
	deadline := time.Now().Add(2 * time.Second)
	for up.hits("/never.jpg") == 0 && time.Now().Before(deadline) {
		time.Sleep(5 * time.Millisecond)
	}
	if n := up.hits("/never.jpg"); n != 1 {
		t.Fatalf("unstaged winner dials = %d, want 1 (fetch-once economics)", n)
	}
}

// TestArtObjectRoute covers the serve route (artwork D5): 401 unauth, 200 for
// client AND admin, the strong hex ETag answering If-None-Match with 304 and
// HEAD with the immutable policy and no body, and 404 — malformed oid or
// missing blob — with ZERO upstream contact.
func TestArtObjectRoute(t *testing.T) {
	st := openAPIStore(t)
	svc := art.NewService(st, t.TempDir())
	up := newArtUpstream(t, nil) // exists only to count: the route must never dial it

	token, err := svc.IngestBytes(context.Background(), "itm_obj", "item", artJPEG(t, 0x77), "")
	if err != nil {
		t.Fatalf("IngestBytes: %v", err)
	}
	sha := token[len("art_"):]
	app := newArtTestApp(t, st, svc, nil)
	objURL := "/api/v1/art/object/" + token

	t.Run("unauthenticated_401", func(t *testing.T) {
		resp := doRequest(t, app.handler, http.MethodGet, objURL, "", "")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want 401", resp.StatusCode)
		}
	})

	t.Run("admin_200_headers", func(t *testing.T) {
		resp := doRequest(t, app.handler, http.MethodGet, objURL, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if ct := resp.Header.Get("Content-Type"); ct != "image/jpeg" {
			t.Fatalf("content-type = %q, want image/jpeg (sniff-declared)", ct)
		}
		if etag := resp.Header.Get("ETag"); etag != `"`+sha+`"` {
			t.Fatalf("etag = %q, want the strong hex tag %q", etag, `"`+sha+`"`)
		}
		if cc := resp.Header.Get("Cache-Control"); cc != "private, immutable" {
			t.Fatalf("cache-control = %q, want private, immutable", cc)
		}
	})

	t.Run("client_200", func(t *testing.T) {
		resp := doRequest(t, app.handler, http.MethodGet, objURL, "", app.client)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200 (browse group admits the paired client)", resp.StatusCode)
		}
	})

	t.Run("etag_revalidates_304", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodGet, objURL, nil)
		req.Header.Set("Authorization", "Bearer "+adminToken)
		req.Header.Set("If-None-Match", `"`+sha+`"`)
		rec := httptest.NewRecorder()
		app.handler.ServeHTTP(rec, req)
		if rec.Code != http.StatusNotModified {
			t.Fatalf("status = %d, want 304", rec.Code)
		}
	})

	t.Run("head_headers_only", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodHead, objURL, nil)
		req.Header.Set("Authorization", "Bearer "+adminToken)
		rec := httptest.NewRecorder()
		app.handler.ServeHTTP(rec, req)
		if rec.Code != http.StatusOK {
			t.Fatalf("status = %d, want 200", rec.Code)
		}
		if cc := rec.Header().Get("Cache-Control"); cc != "private, immutable" {
			t.Fatalf("HEAD cache-control = %q, want the immutable policy", cc)
		}
		if rec.Body.Len() != 0 {
			t.Fatalf("HEAD body = %d bytes, want headers only", rec.Body.Len())
		}
	})

	t.Run("miss_404_no_upstream", func(t *testing.T) {
		for _, oid := range []string{
			"art_" + strings.Repeat("e", 64), // well-formed token, no such blob
			"not-a-token",                    // malformed oid
			"art_" + strings.Repeat("e", 63), // wrong length
		} {
			resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/art/object/"+oid, "", adminToken)
			resp.Body.Close()
			if resp.StatusCode != http.StatusNotFound {
				t.Fatalf("oid %q: status = %d, want 404 (canonical absence)", oid, resp.StatusCode)
			}
		}
		if n := up.total(); n != 0 {
			t.Fatalf("upstream hits = %d, want 0 (serving never fetches)", n)
		}
	})
}

// TestPosterOverrideFamily covers the override verbs (artwork): candidates
// carry served proxy URLs, the pin flips composition, an unknown or
// malformed selection is 400, the reset is an idempotent 204 back to the
// chain, an upload replacement deletes the old pair, and a pinned namespace
// that later vanishes from the document floors silently — the remaining
// chain value (or honest absence) is served while the override row is
// retained and the vanished namespace leaves the candidates. The item mirror
// rides the same verbs with the thumb candidate's client-side leg.
func TestPosterOverrideFamily(t *testing.T) {
	ctx := context.Background()
	st := openAPIStore(t)
	root := t.TempDir()
	svc := art.NewService(st, root)

	first := artJPEG(t, 0x11)
	srv := newArtUpstream(t, map[string][]byte{"/real.jpg": first})
	if _, err := svc.Acquire(ctx, srv.server.URL+"/real.jpg", art.KindPoster); err != nil {
		t.Fatalf("stage poster: %v", err)
	}

	lib, err := st.CreateLibrary(ctx, "serial", "/media/fam", "Family")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	putArtSeries(t, st, lib, "Show", artSeriesDoc("shikimori", srv.server.URL+"/real.jpg"))
	id := seriesIDOf(t, st, lib, "Show")

	app := newArtTestApp(t, st, svc, []titleSourceBinding{
		{ID: "shikimori", Enabled: true},
		{ID: "serial-parser", Enabled: true}, // the chain's second leg — the vanishing-namespace floor falls through to it
	})
	postersURL := "/api/v1/series/" + id + "/posters"
	posterURL := "/api/v1/series/" + id + "/poster"
	proxyOf := func(token string) string { return artObjectPath + token }
	servedArtwork := func(t *testing.T) string {
		t.Helper()
		resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/series?library="+strconv.FormatInt(lib, 10), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("series list = %d, want 200", resp.StatusCode)
		}
		return artworkOf(t, decodeSeriesList(t, resp), "Show")
	}

	t.Run("candidates_before_pin", func(t *testing.T) {
		resp := doRequest(t, app.handler, http.MethodGet, postersURL, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		var got posterCandidatesResponse
		if err := json.NewDecoder(resp.Body).Decode(&got); err != nil {
			t.Fatalf("decode candidates: %v", err)
		}
		if got.Current != "" {
			t.Fatalf("current = %q, want empty (the chain composes)", got.Current)
		}
		if len(got.Candidates) != 1 || got.Candidates[0].Source != "shikimori" {
			t.Fatalf("candidates = %+v, want exactly the staged shikimori poster", got.Candidates)
		}
		if want := proxyOf("art_" + sha256HexOf(first)); got.Candidates[0].URL != want {
			t.Fatalf("staged candidate url = %q, want the proxy URL %q (not the raw remote)", got.Candidates[0].URL, want)
		}
	})

	t.Run("pin_flips_composition", func(t *testing.T) {
		resp := doRequest(t, app.handler, http.MethodPut, posterURL, `{"selection":"src:shikimori"}`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("PUT = %d, want 200", resp.StatusCode)
		}
		// The single-candidate case composes the same URL either way, so the
		// flip reads off the candidates envelope: the pin is the Current.
		cresp := doRequest(t, app.handler, http.MethodGet, postersURL, "", adminToken)
		defer cresp.Body.Close()
		if cresp.StatusCode != http.StatusOK {
			t.Fatalf("posters = %d, want 200", cresp.StatusCode)
		}
		var got posterCandidatesResponse
		if err := json.NewDecoder(cresp.Body).Decode(&got); err != nil {
			t.Fatalf("decode candidates: %v", err)
		}
		if got.Current != "src:shikimori" {
			t.Fatalf("current = %q, want the pinned src:shikimori", got.Current)
		}
		if len(got.Candidates) != 1 || !got.Candidates[0].Current {
			t.Fatalf("candidates = %+v, want the shikimori candidate marked current", got.Candidates)
		}
		if after := servedArtwork(t); after == "" {
			t.Fatal("pinned series lost its artwork field")
		}
	})

	t.Run("unknown_and_malformed_selection_400", func(t *testing.T) {
		for _, sel := range []string{
			`{"selection":"bogus"}`,
			`{"selection":"user:art_` + strings.Repeat("z", 64) + `"}`, // not hex
			`{"selection":"user:art_` + strings.Repeat("a", 63) + `"}`, // wrong length
			`{"selection":"src:"}`,
			`{"nope":1}`,
		} {
			resp := doRequest(t, app.handler, http.MethodPut, posterURL, sel, adminToken)
			resp.Body.Close()
			if resp.StatusCode != http.StatusBadRequest {
				t.Fatalf("selection %s: status = %d, want 400", sel, resp.StatusCode)
			}
		}
	})

	t.Run("reset_idempotent_204", func(t *testing.T) {
		for i := 0; i < 2; i++ {
			resp := doRequest(t, app.handler, http.MethodDelete, posterURL, "", adminToken)
			resp.Body.Close()
			if resp.StatusCode != http.StatusNoContent {
				t.Fatalf("DELETE #%d = %d, want 204", i+1, resp.StatusCode)
			}
		}
	})

	t.Run("upload_replace_deletes_old_pair", func(t *testing.T) {
		body1, ct1 := multipartFile(t, artJPEG(t, 0x33))
		resp := doUpload(t, app.handler, http.MethodPost, posterURL, body1, ct1, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("upload #1 = %d, want 200", resp.StatusCode)
		}
		var rec posterOverrideResponse
		if err := json.NewDecoder(resp.Body).Decode(&rec); err != nil {
			t.Fatalf("decode upload response: %v", err)
		}
		if !strings.HasPrefix(rec.Selection, "user:art_") {
			t.Fatalf("upload selection = %q, want the user:art_<hex> vocabulary", rec.Selection)
		}
		sha1 := rec.Selection[len("user:")+len("art_"):]
		if _, err := os.Stat(filepath.Join(root, sha1, "cropped.jpg")); err != nil {
			t.Fatalf("upload #1 pair missing: %v", err)
		}
		if got := servedArtwork(t); got != proxyOf(rec.Selection[len("user:"):]) {
			t.Fatalf("upload artwork = %q, want the uploaded proxy URL", got)
		}

		body2, ct2 := multipartFile(t, artJPEG(t, 0x44))
		resp2 := doUpload(t, app.handler, http.MethodPost, posterURL, body2, ct2, adminToken)
		defer resp2.Body.Close()
		if resp2.StatusCode != http.StatusOK {
			t.Fatalf("upload #2 = %d, want 200", resp2.StatusCode)
		}
		if _, err := os.Stat(filepath.Join(root, sha1)); !os.IsNotExist(err) {
			t.Fatalf("replaced pair still on disk (err = %v)", err)
		}
	})

	t.Run("item_thumb_mirror", func(t *testing.T) {
		if err := st.PutItem(ctx, store.Item{
			ID: "itm_ep1", ModuleID: "serial", LibraryID: lib, FileID: "ep-1", RelativePath: "Show/s1e1.mkv",
			MediaType: "tv",
			Document:  json.RawMessage(`{"sources":{"frame-grabber":{"thumbnail_path":"/media/f.jpg"}}}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem: %v", err)
		}
		resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/items/itm_ep1/posters", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("item posters = %d, want 200", resp.StatusCode)
		}
		var got posterCandidatesResponse
		if err := json.NewDecoder(resp.Body).Decode(&got); err != nil {
			t.Fatalf("decode item candidates: %v", err)
		}
		if len(got.Candidates) != 1 || got.Candidates[0].Source != artSelectionThumb {
			t.Fatalf("candidates = %+v, want exactly the thumb candidate", got.Candidates)
		}
		want := "/items/itm_ep1/media?variant=thumb"
		if got.Candidates[0].URL != want {
			t.Fatalf("thumb url = %q, want %q (the client-side leg)", got.Candidates[0].URL, want)
		}
		// Pinning the thumb composes the client-side URL on the item wire.
		put := doRequest(t, app.handler, http.MethodPut, "/api/v1/items/itm_ep1/poster", `{"selection":"thumb"}`, adminToken)
		defer put.Body.Close()
		if put.StatusCode != http.StatusOK {
			t.Fatalf("thumb PUT = %d, want 200", put.StatusCode)
		}
		detail := doRequest(t, app.handler, http.MethodGet, "/api/v1/items/itm_ep1", "", adminToken)
		defer detail.Body.Close()
		var wire itemResponse
		if err := json.NewDecoder(detail.Body).Decode(&wire); err != nil {
			t.Fatalf("decode item detail: %v", err)
		}
		if wire.Item.Artwork != want {
			t.Fatalf("thumb artwork = %q, want %q", wire.Item.Artwork, want)
		}
	})

	t.Run("VanishingNamespaceFloor", func(t *testing.T) {
		// Reviewer S1 (artwork 'Pinned namespace vanishes'): a refresh that
		// drops the pinned namespace from the stored document floors
		// silently — composition serves the remaining chain value (or omits
		// the field), never the pinned URL, while the override row survives
		// and the vanished namespace leaves the candidates list.
		second := artJPEG(t, 0x55)
		srv2 := newArtUpstream(t, map[string][]byte{"/second.jpg": second})
		if _, err := svc.Acquire(ctx, srv2.server.URL+"/second.jpg", art.KindPoster); err != nil {
			t.Fatalf("stage second poster: %v", err)
		}
		pinned := proxyOf("art_" + sha256HexOf(first)) // the shikimori poster's proxy URL
		bothNamespaces := func() json.RawMessage {
			return json.RawMessage(`{"sources":{` +
				jsonQuote("shikimori") + `:{"poster":` + jsonQuote(srv.server.URL+"/real.jpg") + `},` +
				jsonQuote("serial-parser") + `:{"poster":` + jsonQuote(srv2.server.URL+"/second.jpg") + `}}}`)
		}
		// serialOnly is the post-refresh shape: the pinned shikimori
		// namespace is GONE; serial-parser keeps its poster (or loses it,
		// "") per row.
		serialOnly := func(serialPoster string) json.RawMessage {
			return json.RawMessage(`{"sources":{` +
				jsonQuote("serial-parser") + `:{"poster":` + jsonQuote(serialPoster) + `}}}`)
		}

		tests := []struct {
			name      string
			relPath   string
			rewritten json.RawMessage   // the stored doc after the refresh drops shikimori
			wantArt   string            // the served artwork post-vanish ("" = field omitted)
			wantCands []posterCandidate // the candidates post-vanish
		}{
			{
				name:      "floors_to_next_chain",
				relPath:   "VanishNext",
				rewritten: serialOnly(srv2.server.URL + "/second.jpg"),
				wantArt:   proxyOf("art_" + sha256HexOf(second)),
				wantCands: []posterCandidate{{Source: "serial-parser", URL: proxyOf("art_" + sha256HexOf(second)), Current: false}},
			},
			{
				name:      "no_usable_chain_omits_artwork",
				relPath:   "VanishGone",
				rewritten: serialOnly(""), // the namespace remains, its poster is gone
				wantArt:   "",
				wantCands: nil,
			},
		}
		for _, tc := range tests {
			t.Run(tc.name, func(t *testing.T) {
				putArtSeries(t, st, lib, tc.relPath, bothNamespaces())
				id := seriesIDOf(t, st, lib, tc.relPath)
				put := doRequest(t, app.handler, http.MethodPut, "/api/v1/series/"+id+"/poster", `{"selection":"src:shikimori"}`, adminToken)
				defer put.Body.Close()
				if put.StatusCode != http.StatusOK {
					t.Fatalf("PUT = %d, want 200", put.StatusCode)
				}
				// Until the namespace vanishes the pin composes the pinned URL.
				served := func(t *testing.T) string {
					t.Helper()
					resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/series?library="+strconv.FormatInt(lib, 10), "", adminToken)
					defer resp.Body.Close()
					if resp.StatusCode != http.StatusOK {
						t.Fatalf("series list = %d, want 200", resp.StatusCode)
					}
					return artworkOf(t, decodeSeriesList(t, resp), tc.relPath)
				}
				if got := served(t); got != pinned {
					t.Fatalf("pre-vanish artwork = %q, want the pinned proxy %q", got, pinned)
				}
				// The refresh rewrites the stored document WITHOUT the
				// shikimori namespace — PutSeries upserts in place, so the
				// row, its id, and the override survive the rewrite.
				putArtSeries(t, st, lib, tc.relPath, tc.rewritten)
				if got := served(t); got != tc.wantArt {
					t.Fatalf("vanished-namespace artwork = %q, want %q (the floor, never the pinned URL)", got, tc.wantArt)
				}
				// The override row is retained and the vanished namespace
				// leaves the candidates.
				cresp := doRequest(t, app.handler, http.MethodGet, "/api/v1/series/"+id+"/posters", "", adminToken)
				defer cresp.Body.Close()
				if cresp.StatusCode != http.StatusOK {
					t.Fatalf("posters = %d, want 200", cresp.StatusCode)
				}
				var got posterCandidatesResponse
				if err := json.NewDecoder(cresp.Body).Decode(&got); err != nil {
					t.Fatalf("decode candidates: %v", err)
				}
				if got.Current != "src:shikimori" {
					t.Fatalf("current = %q, want src:shikimori (the override row is retained)", got.Current)
				}
				if len(got.Candidates) != len(tc.wantCands) {
					t.Fatalf("candidates = %+v, want %d (the vanished namespace dropped)", got.Candidates, len(tc.wantCands))
				}
				for i, want := range tc.wantCands {
					if got.Candidates[i] != want {
						t.Fatalf("candidate #%d = %+v, want %+v", i, got.Candidates[i], want)
					}
				}
			})
		}
	})
}

// TestArtWalkSkipGolden drives the walk predicate from the committed golden
// fixture internal/api/testdata/golden/missing_art.json (artwork): every
// sample's walk_skip verdict IS the predicate's spec. The composition legs
// replay the boundary against a local upstream — the fixture's missing path
// served from the test host (the fixture's relative sample already pins that
// the rule is the PATH prefix, not the host): a placeholder-first chain
// falls through to the next namespace, the placeholder is never fetched
// (the per-path hit counter stays zero), the placeholder-only document
// omits the field, and the candidates list offers no placeholder.
func TestArtWalkSkipGolden(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("testdata", "golden", "missing_art.json"))
	if err != nil {
		t.Fatalf("read golden fixture: %v", err)
	}
	var fixture struct {
		Samples []struct {
			URL        string `json:"url"`
			PluginDrop bool   `json:"plugin_drop"`
			WalkSkip   bool   `json:"walk_skip"`
		} `json:"samples"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("decode golden fixture: %v", err)
	}
	if len(fixture.Samples) < 3 {
		t.Fatalf("golden fixture carries %d samples, want >= 3", len(fixture.Samples))
	}
	// The predicate pin: either side drifting alone fails its own suite.
	for _, s := range fixture.Samples {
		if got := placeholderPoster(s.URL); got != s.WalkSkip {
			t.Errorf("placeholderPoster(%q) = %v, want walk_skip %v", s.URL, got, s.WalkSkip)
		}
	}

	// The first walk_skip sample's PATH, replayed from the local upstream so
	// any fetch attempt is observable (and never leaves the machine).
	var missingPath string
	for _, s := range fixture.Samples {
		if !s.WalkSkip {
			continue
		}
		parsed, err := url.Parse(s.URL)
		if err != nil {
			t.Fatalf("parse fixture url %q: %v", s.URL, err)
		}
		missingPath = parsed.Path
		break
	}
	if missingPath == "" {
		t.Fatal("fixture lacks a walk_skip sample")
	}

	st := openAPIStore(t)
	svc := art.NewService(st, t.TempDir())
	up := newArtUpstream(t, map[string][]byte{"/real.jpg": artJPEG(t, 0x9E)})
	placeholder := up.server.URL + missingPath
	real := up.server.URL + "/real.jpg"

	lib, err := st.CreateLibrary(context.Background(), "serial", "/media/golden", "Golden")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	// fall_through: the first-enabled namespace's poster is a placeholder,
	// the next namespace carries a real one — the walk continues past it.
	putArtSeries(t, st, lib, "Fall", json.RawMessage(`{"sources":{`+
		jsonQuote("shikimori")+`:{"poster":`+jsonQuote(placeholder)+`},`+
		jsonQuote("serial-parser")+`:{"poster":`+jsonQuote(real)+`}}}`))
	// placeholder_only: honest absence — no artwork, no fetch, no candidate.
	putArtSeries(t, st, lib, "Only", artSeriesDoc("shikimori", placeholder))

	app := newArtTestApp(t, st, svc, []titleSourceBinding{
		{ID: "shikimori", Enabled: true},
		{ID: "serial-parser", Enabled: true},
	})
	resp := doRequest(t, app.handler, http.MethodGet, "/api/v1/series?library="+strconv.FormatInt(lib, 10), "", adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}
	items := decodeSeriesList(t, resp)
	if got := artworkOf(t, items, "Fall"); got != real {
		t.Fatalf("fall-through artwork = %q, want the next namespace's real URL %q", got, real)
	}
	if got := artworkOf(t, items, "Only"); got != "" {
		t.Fatalf("placeholder-only artwork = %q, want the field omitted", got)
	}
	if n := up.hits(missingPath); n != 0 {
		t.Fatalf("placeholder fetched %d times, want 0 (a placeholder is never fetched)", n)
	}

	// The candidates list offers no placeholder: exactly the real poster.
	cresp := doRequest(t, app.handler, http.MethodGet,
		"/api/v1/series/"+seriesIDOf(t, st, lib, "Fall")+"/posters", "", adminToken)
	defer cresp.Body.Close()
	if cresp.StatusCode != http.StatusOK {
		t.Fatalf("candidates = %d, want 200", cresp.StatusCode)
	}
	var cands posterCandidatesResponse
	if err := json.NewDecoder(cresp.Body).Decode(&cands); err != nil {
		t.Fatalf("decode candidates: %v", err)
	}
	if len(cands.Candidates) != 1 || cands.Candidates[0].Source != "serial-parser" {
		t.Fatalf("candidates = %+v, want exactly the real serial-parser poster (the placeholder excluded)", cands.Candidates)
	}
}
